 "content": "def transform(grid):
    """Find translations of the marked shape on the dominant nonzero background."""
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 1, 5)]
    if not markers:
        return [row[:] for row in grid]
    color = grid[markers[0][0]][markers[0][1]]
    markers = [(r, c) for r, c in markers if grid[r][c] == color]
    minr = min(r for r, c in markers)
    minc = min(c for r, c in markers)
    shape = [(r-minr, c-minc) for r, c in markers]
    # The noisy field's repeated/background color is the nonzero color other than marker.
    counts = {}
    for row in grid:
        for v in row:
            if v not in (0, color):
                counts[v] = counts.get(v, 0) + 1
    # For ARC instances, zero is the noise background's alternative; select its complement.
    vals = {}
    for row in grid:
        for v in row:
            if v != color:
                vals[v] = vals.get(v, 0) + 1
    bg = max(vals, key=vals.get)
    out = [row[:] for row in grid]
    H = max(r for r, c in shape) + 1
    W = max(c for r, c in shape) + 1
    for r0 in range(h-H+1):
        for c0 in range(w-W+1):
            if all(grid[r0+dr][c0+dc] == bg for dr, dc in shape):
                for dr, dc in shape:
                    out[r0+dr][c0+dc] = color
    return out
